/**
 * Update 39A — readiness fixes, batch A (FAKE data only: the demo school + the Test School).
 *   C-1 the class page never resets finished work and writes nothing when nothing changed
 *   C-2 the teacher's student page never crashes on an answer; Review my mistakes goes through the engine
 *   I-3/4/5 one open alert per student and kind, refreshed not duplicated; generated by the daily job; reports count them
 *   WEAK_SKILL follows mastery (rapid guesses excluded, hidden skill never named)
 *   teacher follow-up counts only the teacher's own work · manual MAP entry notifies, duplicates and dates are checked
 *   selector fallback for bank gaps · one student status across pages · one answer count
 *   test-school removal leaves no orphan rows · admin styles are one module · small fixes (S-8 … S-15)
 */
import { before, describe, test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import type { DatabaseSync } from "node:sqlite";
import type { SqliteRepo } from "../scripts/db/sqlite-repo";
import { parseSchema } from "../scripts/db/schema-ddl";
import { resolveActor } from "../src/server/auth/actor";
import { ForbiddenError, type Actor } from "../src/server/auth/rbac";
import { ownershipEdges, resetTestEnvironment, seedTestEnvironment, TEST_SCHOOL_CODE } from "../src/server/seeding/test-env";
import { readableClasses } from "../src/server/teacher/coordinators";
import { loadQuestionItems } from "../src/server/practice/items";
import { classAssignments } from "../src/server/teacher/assignments";
import { assignQuestions, cancelAssignment } from "../src/server/teacher/assign";
import { answerText, answerValue, classOverview, studentDetail, teacherClasses, withGradeSuffix } from "../src/server/teacher/queries";
import { reviewSet, submitReview } from "../src/server/teacher/classroom";
import { alertList, findAlerts, isWeakSkill, MERGED, scanAlerts } from "../src/server/insights/alerts";
import { scanDailyAlerts } from "../src/server/insights/daily";
import { isSystemAssignment, teacherFollowup } from "../src/server/insights/teacher-followup";
import { saveMapEntry } from "../src/server/map/map-entry";
import { selectNextItem, MAX_ABOVE_THETA } from "../src/adaptive/selector";
import { DEFAULT_ADAPTIVE } from "../src/config/engine";
import { reconcileStatus, intensityFor } from "../src/server/insights/student-status";
import { classProgress } from "../src/server/insights/progress";
import { parentReport } from "../src/server/insights/parent-report";
import { practiceStats } from "../src/server/insights/student-data";
import { latestDiagnostic } from "../src/server/assessment/diagnostic";
import { bandFor } from "../src/server/diagnostic/standards";
import { computeTiers, LOCK_DAYS, setTierManually } from "../src/server/tiers/tiers";
import { tierRows } from "../src/server/tiers/views";
import { moveStudent } from "../src/server/admin/users";
import { rosterBackup } from "../src/server/admin/roster-clean";
import { readRiseProjection } from "../src/server/readrise/engine";
import { RR_MIN } from "../src/server/readrise/level";
import { demoDatabase } from "./helpers/db";

const DAY = 86_400_000;
const ROOT = process.cwd();

describe("Update 39A · readiness fixes", () => {
  let repo: SqliteRepo; let db: DatabaseSync;
  let admin: Actor; let teacher: Actor; let other: Actor;
  let classId = ""; let otherClassId = ""; let students: string[] = []; let skillId = ""; let qids: string[] = [];
  const now = new Date(Date.UTC(2026, 9, 14, 9)); // a Wednesday
  const actorFor = async (u: string) => resolveActor(repo, (await repo.findUnique("User", { username: u }))!);
  const studentActor = async (id: string) => resolveActor(repo, (await repo.findUnique("User", { id: (await repo.findUnique("Student", { id }))!.userId }))!);
  /** counts writes to one table while f runs */
  async function writesTo<T>(model: string, f: () => Promise<T>): Promise<{ value: T; writes: number }> {
    const r = repo as unknown as Record<string, (...a: unknown[]) => Promise<unknown>>;
    const orig = r.updateMany; let writes = 0;
    r.updateMany = (...a: unknown[]) => { if (a[0] === model) writes++; return orig.apply(repo, a); };
    try { return { value: await f(), writes }; } finally { r.updateMany = orig; }
  }
  async function answers(studentId: string, ids: string[], ok: boolean[], daysAgo: number, rapid = false) {
    const at = new Date(now.getTime() - daysAgo * DAY);
    const sess = await repo.create("PracticeSession", { studentId, skillId, mode: "ADAPTIVE_PRACTICE", startedAt: at });
    for (let i = 0; i < ids.length; i++) await repo.create("QuestionAttempt", { sessionId: sess.id, studentId, questionId: ids[i], skillId, response: { value: "Z" }, isCorrect: ok[i], responseMs: rapid ? 900 : 25_000, rapidGuess: rapid, difficultyB: 0, createdAt: at });
  }

  before(async () => {
    ({ repo, db } = await demoDatabase());
    await seedTestEnvironment(repo, { root: ROOT, passwordHash: "x".repeat(60), practice: "none" });
    admin = await actorFor("test.admin");
    for (const i of [1, 2, 3, 4, 5, 6]) {
      const t = await actorFor(`test.teacher.${i}`);
      const c = (await readableClasses(repo, t))[0];
      if (!c) continue;
      const g = Number((await repo.findUnique("Grade", { id: c.gradeId }))!.level);
      if (g === 4 && !classId) { teacher = t; classId = String(c.id); } else if (g === 4 && !otherClassId) { other = t; otherClassId = String(c.id); }
    }
    assert.ok(classId && otherClassId, "two Grade 4 classes");
    students = (await repo.findMany("ClassMembership", { classId, leftAt: null })).map((m) => String(m.studentId)).sort();
    const g4 = (await repo.findMany("Grade", { schoolId: admin.schoolId, level: 4 }))[0];
    const cur = (await repo.findMany("Curriculum", { gradeId: g4.id }))[0];
    for (const k of await repo.findMany("Skill", { curriculumId: cur.id })) {
      const items = await loadQuestionItems(repo, (await repo.findMany("Question", { skillId: k.id, status: "PUBLISHED" })).map((q) => String(q.id)));
      if (items.length >= 6 && items.every((i) => i.type !== "SHORT_ANSWER")) { skillId = String(k.id); qids = items.map((i) => i.questionId); break; }
    }
    assert.ok(skillId, "a skill with questions");
    await repo.updateMany("Student", { id: { in: students } }, { createdAt: new Date(now.getTime() - 60 * DAY) });
  });

  // ------------------------------------------------------------------ C-1
  test("C-1: opening the class page never resets finished work, and a second view writes nothing", async () => {
    const set = await assignQuestions(repo, teacher, { classId, questionIds: qids.slice(0, 5), title: "C1 set", exactTitle: true, dueAt: new Date(now.getTime() + DAY) }, now);
    // student 0 finished it (e.g. marked done before an update), no answers in this database
    await repo.updateMany("AssignmentStudent", { assignmentId: set.assignmentId, studentId: students[0] }, { status: "COMPLETED", progress: 1, completedAt: now });
    // a system set with no target skills and no question set (the old code read it as 0 %)
    const legacy = await repo.create("Assignment", { classId, createdById: (await repo.findUnique("Teacher", { userId: teacher.userId }))!.id, title: "Legacy set", target: "ASSESSMENT", createdAt: now });
    await repo.create("AssignmentStudent", { assignmentId: legacy.id, studentId: students[1], status: "COMPLETED", progress: 1, completedAt: now });
    const later = new Date(now.getTime() + 3 * DAY); // past the due date
    const first = await writesTo("AssignmentStudent", () => classAssignments(repo, teacher, classId, later));
    const row = (await repo.findMany("AssignmentStudent", { assignmentId: set.assignmentId, studentId: students[0] }))[0];
    assert.equal(row.status, "COMPLETED", "finished work stays finished");
    assert.ok(row.completedAt, "completedAt kept");
    assert.equal((await repo.findMany("AssignmentStudent", { assignmentId: legacy.id }))[0].status, "COMPLETED", "a set without target skills is never recomputed");
    assert.ok((await repo.findMany("AssignmentStudent", { assignmentId: set.assignmentId, studentId: students[2] }))[0].status === "OVERDUE", "unfinished work does become overdue");
    assert.ok(first.writes > 0, "the first view after the due date updates what changed");
    const second = await writesTo("AssignmentStudent", () => classAssignments(repo, teacher, classId, later));
    assert.equal(second.writes, 0, "a second view writes nothing");
    const sum = second.value.find((a) => a.id === set.assignmentId)!;
    assert.equal(sum.counts.COMPLETED, 1);
  });

  // ------------------------------------------------------------------ C-2
  test("C-2: the teacher's student page reads every stored answer shape without crashing", async () => {
    assert.equal(answerValue({ value: "B" }), "B");
    assert.equal(answerValue("B"), "B", "older review answers stored the raw value");
    assert.equal(answerText(undefined), "");
    assert.equal(answerText(null), "");
    assert.equal(answerText({ a: 1 }), '{"a":1}');
    const sid = students[6];
    const sess = await repo.create("PracticeSession", { studentId: sid, mode: "ADAPTIVE_PRACTICE", startedAt: now, endedAt: now, endReason: "REVIEW" });
    for (const response of [{}, "B", 2, [], { value: undefined }] as unknown[]) await repo.create("QuestionAttempt", { sessionId: sess.id, studentId: sid, questionId: qids[0], skillId, response: response as never, isCorrect: false, responseMs: 20_000, difficultyB: 0, createdAt: now });
    const d = await studentDetail(repo, teacher, sid);
    assert.ok(d.recent.length >= 5 && d.recent.every((r) => typeof r.answer === "string"));
  });

  test("C-2: Review my mistakes stores { value }, the real time, flags rapid answers and updates mastery like practice", async () => {
    const sid = students[7];
    await answers(sid, qids.slice(0, 4), [false, false, false, false], 2);
    const me = await studentActor(sid);
    const set = await reviewSet(repo, me, now);
    assert.ok(set.questions.length >= 3);
    const [q1, q2, q3] = set.questions.map((q) => q.questionId);
    const before = Number((await repo.findUnique("StudentSkillMastery", { studentId: sid, skillId }))?.attempts ?? 0);
    const r = await submitReview(repo, me, Object.fromEntries(set.questions.map((q) => [q.questionId, null])), now, { [q1]: 31_000, [q2]: 300 });
    assert.equal(r.total, set.questions.length);
    const rows = (await repo.findMany("QuestionAttempt", { studentId: sid, createdAt: now }));
    assert.equal(rows.length, set.questions.length);
    for (const a of rows) assert.ok(a.response && typeof a.response === "object" && "value" in (a.response as object), "practice shape { value }");
    const byQ = new Map(rows.map((a) => [String(a.questionId), a]));
    assert.equal(Number(byQ.get(q1)!.responseMs), 31_000, "the time the page measured");
    assert.equal(Boolean(byQ.get(q2)!.rapidGuess), true, "a 0.3-second answer is a rapid guess");
    assert.notEqual(Number(byQ.get(q3)!.responseMs), 20_000, "no fake 20 s");
    assert.equal(Boolean(byQ.get(q3)!.rapidGuess), false, "no time sent: never treated as a rapid guess");
    const after = Number((await repo.findUnique("StudentSkillMastery", { studentId: sid, skillId }))!.attempts);
    assert.equal(after - before, set.questions.length, "mastery counted every review answer");
    const logs = await repo.findMany("AdaptiveDecisionLog", { studentId: sid, reasonCode: "REVIEW" });
    assert.equal(logs.length, set.questions.length, "the engine logged each answer");
  });

  // ------------------------------------------------------------------ alerts
  test("WEAK_SKILL follows mastery: enough evidence, rapid guesses excluded", () => {
    assert.equal(isWeakSkill({ score: 30, attempts: 20, components: { effectiveN: 9 }, validRecent: 8 }), true);
    assert.equal(isWeakSkill({ score: 45, attempts: 20, components: { effectiveN: 9 }, validRecent: 8 }), false, "Approaching or above is not weak");
    assert.equal(isWeakSkill({ score: 20, attempts: 20, components: { effectiveN: 3 }, validRecent: 8 }), false, "not enough evidence (rapid guesses weigh 0.2)");
    assert.equal(isWeakSkill({ score: 20, attempts: 30, components: { effectiveN: 9 }, validRecent: 2 }), false, "rapid guesses are not counted as answers");
  });

  test("alerts: one open alert per student and kind, refreshed (not duplicated) the next week; hidden skill never named", async () => {
    const sid = students[0];
    const ten = Array.from({ length: 10 }, (_, i) => qids[i % qids.length]);
    await answers(sid, ten, ten.map((_, i) => i < 2), 2);
    await repo.upsert("StudentSkillMastery", { studentId: sid, skillId }, { studentId: sid, skillId, score: 15, band: "BEGINNING", attempts: 10, correct: 2, lastPracticedAt: new Date(now.getTime() - 2 * DAY), components: { effectiveN: 8 }, updatedAt: now }, { score: 15, attempts: 10, correct: 2, components: { effectiveN: 8 }, lastPracticedAt: new Date(now.getTime() - 2 * DAY) });
    // a weak hidden “Unclassified (Curriculum Map)” skill too
    const k = (await repo.findUnique("Skill", { id: skillId }))!;
    const hidden = await repo.create("Skill", { curriculumId: k.curriculumId, familyId: k.familyId, code: "G4.curriculum-map-unclassified", name: "Unclassified (Curriculum Map)", domain: k.domain, category: k.category, isActive: false });
    const hs = await repo.create("PracticeSession", { studentId: sid, skillId: hidden.id, mode: "ADAPTIVE_PRACTICE", startedAt: now });
    for (let i = 0; i < 8; i++) await repo.create("QuestionAttempt", { sessionId: hs.id, studentId: sid, questionId: qids[0], skillId: hidden.id, response: { value: "Z" }, isCorrect: false, responseMs: 25_000, difficultyB: 0, createdAt: new Date(now.getTime() - DAY) });
    await repo.create("StudentSkillMastery", { studentId: sid, skillId: hidden.id, score: 5, band: "BEGINNING", attempts: 8, correct: 0, lastPracticedAt: now, components: { effectiveN: 8 }, updatedAt: now });
    const found = (await findAlerts(repo, admin.schoolId!, now)).filter((f) => f.studentId === sid && f.kind === "WEAK_SKILL");
    assert.ok(found.length >= 1);
    assert.ok(found.every((f) => !/Unclassified/.test(f.detail)), "the hidden skill is never named");
    await scanAlerts(repo, admin.schoolId!, now, true);
    const open1 = await repo.findMany("StudentAlert", { studentId: sid, kind: "WEAK_SKILL", status: "OPEN" });
    assert.equal(open1.length, 1);
    const nextWeek = new Date(now.getTime() + 7 * DAY);
    await scanAlerts(repo, admin.schoolId!, nextWeek, true);
    const open2 = await repo.findMany("StudentAlert", { studentId: sid, kind: "WEAK_SKILL", status: "OPEN" });
    assert.equal(open2.length, 1, "still one open alert the next week");
    assert.equal(open2[0].id, open1[0].id, "the same alert, refreshed");
    assert.match(String(open2[0].detail), /Still true on 2026-10-21 \(open since 2026-10-14\)/);
    const kinds = (await repo.findMany("StudentAlert", { schoolId: admin.schoolId, status: "OPEN" })).map((a) => `${a.studentId}|${a.kind}`);
    assert.equal(new Set(kinds).size, kinds.length, "never two open alerts of one kind for one student");
  });

  test("alerts: older duplicates are merged; class report, class list and Alerts page count the same open alerts", async () => {
    const sid = students[3];
    for (const key of ["LATE_WORK|2026-W40", "LATE_WORK|2026-W41"]) await repo.create("StudentAlert", { schoolId: admin.schoolId, classId, studentId: sid, kind: "LATE_WORK", key, detail: "2 tasks not started by their due date.", status: "OPEN", createdAt: new Date(now.getTime() - 14 * DAY) });
    await scanAlerts(repo, admin.schoolId!, new Date(now.getTime() + 8 * DAY), true);
    const late = await repo.findMany("StudentAlert", { studentId: sid, kind: "LATE_WORK" });
    assert.equal(late.filter((a) => a.status === "OPEN").length, 1);
    assert.ok(late.filter((a) => a.status === MERGED).length >= 1, "the newer duplicates are merged");
    const page = await alertList(repo, teacher, { status: "ALL" }, now);
    assert.ok(page.every((a) => (a.status as string) !== MERGED), "merged rows are not shown");
    const ids = new Set(students);
    const open = (await repo.findMany("StudentAlert", { status: "OPEN" })).filter((a) => ids.has(String(a.studentId))).length;
    const o = await classOverview(repo, teacher, classId, { from: new Date(now.getTime() - 365 * DAY), to: now });
    assert.equal(o.students.reduce((t, s) => t + s.openAlerts, 0), open, "class report = Alerts page (StudentAlert OPEN)");
    assert.equal((await teacherClasses(repo, teacher)).find((c) => c.classId === classId)!.openAlerts, open, "class list = Alerts page");
  });

  test("alerts are generated by the daily job (not only when a page is opened)", async () => {
    await repo.deleteMany("StudentAlert", { schoolId: admin.schoolId });
    const r = await scanDailyAlerts(repo, admin.schoolId!, new Date(now.getTime() + 9 * DAY));
    assert.ok(r.alerts > 0, JSON.stringify(r));
    const src = readFileSync(join(ROOT, "src/server/insights/daily.ts"), "utf8");
    assert.match(src, /const alerts = await scanDailyAlerts\(repo, schoolId, now\)/, "runDaily calls it");
    assert.doesNotMatch(readFileSync(join(ROOT, "src/app/teacher/classes/[classId]/page.tsx"), "utf8"), /scanInterventions/, "the class page is read-only");
  });

  // ------------------------------------------------------------------ teacher follow-up
  test("teacher follow-up counts only the teacher's own work (not Weekly Checks, re-checks, reteach, Diagnostic)", async () => {
    assert.equal(isSystemAssignment({ title: "Weekly Check · 2026-W42", curriculumPlanId: "WEEKLY_CHECK" }), true);
    assert.equal(isSystemAssignment({ title: "Re-check: Make Inferences" }), true);
    assert.equal(isSystemAssignment({ title: "Make Inferences", note: "Extra practice on this skill, then a short re-check." }), true);
    assert.equal(isSystemAssignment({ title: "Diagnostic Test · BOY (Beginning of Year)", note: "Beginning of Year Diagnostic Test" }), true);
    assert.equal(isSystemAssignment({ title: "Unit 1 · Concept Vocabulary (adaptive: Below → On → Above)" }), false);
    const count = async () => (await teacherFollowup(repo, admin, now)).rows.find((r) => r.userId === other.userId)!.assignments30;
    const before0 = await count();
    const tid = (await repo.findUnique("Teacher", { userId: other.userId }))!.id;
    await repo.create("Assignment", { classId: otherClassId, createdById: tid, title: "Weekly Check · 2026-W42", target: "ASSESSMENT", curriculumPlanId: "WEEKLY_CHECK", note: "Weekly Check", createdAt: now });
    await repo.create("Assignment", { classId: otherClassId, createdById: tid, title: "Re-check: Make Inferences", target: "ASSESSMENT", createdAt: now });
    assert.equal(await count(), before0, "system work is not the teacher's follow-up");
    await assignQuestions(repo, other, { classId: otherClassId, questionIds: qids.slice(0, 3), title: "Teacher's own set", exactTitle: true }, now);
    assert.equal(await count(), before0 + 1);
  });

  // ------------------------------------------------------------------ MAP
  test("manual MAP entry: students are notified; a student twice is a problem row; a Winter dated before Fall is warned", async () => {
    const [a, b] = [students[8], students[9]];
    const userOf = async (id: string) => String((await repo.findUnique("Student", { id }))!.userId);
    const rows = (r: Record<string, string>[]) => r.map((x) => ({ studentId: x.id, rit: x.rit, percentile: "", projection: "", lexile: "", goals: {} }));
    const fall = await saveMapEntry(repo, teacher, { classId, subject: "READING", season: "FALL", year: 2026, rows: rows([{ id: a, rit: "201" }, { id: b, rit: "195" }]) }, now);
    assert.equal(fall.imported, 2, JSON.stringify(fall.errors));
    for (const id of [a, b]) assert.equal((await repo.findMany("Notification", { userId: await userOf(id), title: "🗺️ Your MAP results are in" })).length, 1, "notified like the file import");
    const twice = await saveMapEntry(repo, teacher, { classId, subject: "READING", season: "FALL", year: 2026, rows: rows([{ id: a, rit: "202" }, { id: a, rit: "209" }]) }, new Date(now.getTime() + 60_000));
    assert.ok(twice.errors.some((e) => /more than once/.test(e.message)), JSON.stringify(twice.errors));
    const kept = (await repo.findMany("MapResult", { studentId: a, termName: "Fall 2026", goalName: null }));
    assert.deepEqual(kept.map((r) => Number(r.rit)), [202], "the first row is kept, not the last");
    const winter = await saveMapEntry(repo, teacher, { classId, subject: "READING", season: "WINTER", year: 2026, rows: rows([{ id: b, rit: "199" }]) }, new Date(now.getTime() + 120_000));
    assert.ok(winter.errors.some((e) => /before these students' Fall test/.test(e.message) && /2027/.test(e.message)), JSON.stringify(winter.errors));
  });

  // ------------------------------------------------------------------ selector
  test("selector: never more than 2 levels above the student; ends the set on a content gap", () => {
    const cfg = { ...DEFAULT_ADAPTIVE };
    const item = (id: string, b: number, level = 4) => ({ id, skillId: "s", b, a: 1, c: 0, level, estimatedSeconds: 40 } as never);
    const hard = [item("h1", 1.5, 6), item("h2", 2.25, 7)];
    const gap = selectNextItem({ mode: "PRACTICE", theta: -1.9, previousTargetB: null, candidates: hard, recentItemIds: [], recentCorrect: [], prerequisites: [], config: cfg, random: () => 0.99 });
    assert.equal(gap.itemId, null);
    assert.equal(gap.reasonCode, "NO_ITEM_IN_RANGE");
    assert.match(gap.reason, /Content gap/);
    const seen = selectNextItem({ mode: "PRACTICE", theta: -1.9, previousTargetB: null, candidates: [...hard, item("e1", -1.5, 2), item("e2", -1.6, 2)], recentItemIds: ["e1", "e2"], recentCorrect: [true, true], prerequisites: [], config: { ...cfg, noRepeatWindow: 10 }, random: () => 0.99 });
    assert.equal(seen.itemId, null, "the easy questions were just answered: the set ends rather than jumping to a hard one");
    for (const r of [0, 0.5, 0.99]) {
      const far = selectNextItem({ mode: "PRACTICE", theta: 0, previousTargetB: null, candidates: [item("n1", 1.4), item("n2", 1.45), item("f1", -1.4 + 4), item("f2", 1.49)], recentItemIds: [], recentCorrect: [], prerequisites: [], config: cfg, random: () => r });
      assert.ok(far.itemId && ["n1", "n2", "f2"].includes(far.itemId), "only the nearest items when the bank has a gap");
      assert.ok(far.itemId !== "f1", `never above θ + ${MAX_ABOVE_THETA}`);
    }
  });

  // ------------------------------------------------------------------ one status
  test("one student status: the tier wins over contradictions; intensity follows the tier", async () => {
    assert.equal(reconcileStatus({ status: "ON_TRACK", why: "80% correct on the platform (last 30 days)" }, { tier: 3, reason: "two checks under 60%" }).status, "AT_RISK");
    assert.equal(reconcileStatus({ status: "MET", why: "Spring 210 reached the target 205." }, { tier: 3, reason: "x" }).status, "AT_RISK");
    assert.equal(reconcileStatus({ status: "AT_RISK", why: "Fall 2026: 18th percentile (low)." }, { tier: 1, reason: "ok" }).status, "ON_TRACK", "an old MAP note does not override Tier 1");
    assert.equal(reconcileStatus({ status: "AT_RISK", why: "40% correct on the platform (last 30 days)." }, { tier: 1, reason: "ok" }).status, "AT_RISK", "current platform evidence is kept");
    assert.equal(intensityFor({ tier: 1, reason: "" }, "INTENSIVE"), "CORE");
    assert.equal(intensityFor({ tier: 3, reason: "" }, "CORE"), "INTENSIVE");
    // integration: a Tier-3 student who practises well is never “On track” on the progress page or “good progress” at home
    const sid = students[10];
    const ten = Array.from({ length: 12 }, (_, i) => qids[i % qids.length]);
    await answers(sid, ten, ten.map(() => true), 1);
    await setTierManually(repo, teacher, { studentId: sid, tier: 3, reason: "Struggles in class reading" }, now);
    const p = await classProgress(repo, teacher, classId, "READING", now);
    const row = p.rows.find((r) => r.studentId === sid)!;
    assert.equal(row.status, "AT_RISK");
    assert.equal(row.intensity === null || row.intensity === "INTENSIVE", true);
    const fam = await parentReport(repo, teacher, sid, now);
    assert.doesNotMatch(fam.summary.en, /good progress/);
  });

  test("one answer count: every saved answer is counted (review answers too); placement reads the Diagnostic Test", async () => {
    const sid = students[6]; // has review-shaped answers that never reached mastery
    const all = await repo.count("QuestionAttempt", { studentId: sid });
    assert.equal((await practiceStats(repo, [sid], now)).get(sid)!.answers, all);
    assert.equal(await latestDiagnostic(repo, sid), null);
    const t = await repo.create("DiagnosticTest", { schoolId: admin.schoolId, grade: 4, year: "2026-27", period: "BOY", title: "BOY", assessmentId: (await repo.findMany("Assessment", {}))[0].id, status: "OPEN", createdAt: now } as never).catch(() => null);
    if (t) {
      await repo.create("DiagnosticScore", { diagnosticId: t.id, studentId: sid, assignmentId: "x", correct: 30, total: 40, pct: 75, level: "ON", byStandard: [], byStrand: [{ strand: "LIT", correct: 9, total: 10 }, { strand: "INFO", correct: 4, total: 10 }], completedAt: now });
      const d = await latestDiagnostic(repo, sid);
      assert.ok(d && /On Level/.test(d.proficiency), "Placement shows the Diagnostic Test, not “Not taken”");
      assert.deepEqual(d!.strong, ["Literature"]);
    }
    assert.equal(bandFor(79.2, "ON").name, "Proficient", "never “On Level · Advanced”");
    assert.equal(bandFor(90, "ABOVE").name, "Advanced");
    assert.equal(bandFor(30, "BELOW").key, "INTENSIVE");
  });

  // ------------------------------------------------------------------ small fixes
  test("S-8: a teacher's tier stays, and after 6 weeks the rules only suggest", async () => {
    const sid = students[11];
    await setTierManually(repo, teacher, { studentId: sid, tier: 3, reason: "Teacher's judgement" }, now);
    const soon = new Date(now.getTime() + 10 * DAY);
    assert.match((await tierRows(repo, [sid], soon))[0].lockNote ?? "", /review on 2026-11-25/);
    const later = new Date(now.getTime() + (LOCK_DAYS + 1) * DAY);
    await computeTiers(repo, admin.schoolId!, later, { studentIds: [sid], route: false });
    const t = (await repo.findUnique("StudentTier", { studentId: sid }))!;
    assert.equal(Number(t.tier), 3, "the teacher's tier is never changed by the rules");
    assert.equal(Boolean(t.locked), true);
    const sug = await repo.findMany("TierChange", { studentId: sid, source: "SUGGEST" });
    const note = (await tierRows(repo, [sid], later))[0].lockNote ?? "";
    assert.match(note, /Review due/);
    if (sug.length) assert.match(note, /the rules suggest Tier [12]/);
  });

  test("S-9/S-10: a transfer withdraws unfinished old-class work (finished work stays); a new grade clears the old levels", async () => {
    const sid = students[12];
    const tid = (await repo.findUnique("Teacher", { userId: teacher.userId }))!.id;
    const open = await repo.create("Assignment", { classId, createdById: tid, title: "Open work", target: "ASSESSMENT", createdAt: now });
    const done = await repo.create("Assignment", { classId, createdById: tid, title: "Done work", target: "ASSESSMENT", createdAt: now });
    await repo.create("AssignmentStudent", { assignmentId: open.id, studentId: sid, status: "OVERDUE", progress: 0 });
    await repo.create("AssignmentStudent", { assignmentId: done.id, studentId: sid, status: "COMPLETED", progress: 1, completedAt: now });
    await repo.create("StudentLevel", { studentId: sid, level: "BELOW", source: "TEACHER" });
    const userId = String((await repo.findUnique("Student", { id: sid }))!.userId);
    await moveStudent(repo, admin, userId, otherClassId, now);
    assert.equal((await repo.findMany("AssignmentStudent", { assignmentId: open.id, studentId: sid })).length, 0, "not on the list as overdue");
    assert.equal((await repo.findMany("AssignmentStudent", { assignmentId: done.id, studentId: sid })).length, 1, "finished work stays in the history");
    assert.ok(await repo.findUnique("StudentLevel", { studentId: sid }), "same grade: the level stays");
    const g5class = (await repo.findMany("Class", { schoolId: admin.schoolId })).find(async () => true);
    const grades = await repo.findMany("Grade", { schoolId: admin.schoolId });
    const g5 = grades.find((g) => Number(g.level) === 5)!;
    const c5 = (await repo.findMany("Class", { schoolId: admin.schoolId, gradeId: g5.id }))[0];
    void g5class;
    await moveStudent(repo, admin, userId, String(c5.id), now);
    assert.equal(await repo.findUnique("StudentLevel", { studentId: sid }), null, "another grade: the old grade's level is cleared");
    assert.equal((await repo.findMany("AuditLog", { entityId: sid, action: "level.reset" })).length, 1);
  });

  test("S-11: a teacher can cancel their own assignment (soft delete, audited); another teacher cannot", async () => {
    const a = await assignQuestions(repo, teacher, { classId, questionIds: qids.slice(0, 3), title: "To cancel", exactTitle: true }, now);
    await assert.rejects(cancelAssignment(repo, other, a.assignmentId, now), ForbiddenError);
    const r = await cancelAssignment(repo, teacher, a.assignmentId, now);
    assert.equal(r.title, "To cancel");
    assert.ok((await repo.findUnique("Assignment", { id: a.assignmentId }))!.deletedAt);
    assert.equal((await repo.findMany("AuditLog", { entityId: a.assignmentId, action: "assignment.cancel" })).length, 1);
    await assert.rejects(cancelAssignment(repo, teacher, a.assignmentId, now), ForbiddenError, "already cancelled");
    const src = readFileSync(join(ROOT, "src/app/teacher/assignments/[assignmentId]/actions.ts"), "utf8");
    assert.match(src.slice(src.indexOf("export async function cancelAssignmentAction")), /^[^]*?requireActor\(/, "the action checks the session in its own body");
  });

  test("S-13 / S-15 / S-1 / S-21: grade on duplicate skill names, a smaller roster backup, per-IP limit from env, ReadRise projection on the scale", async () => {
    assert.deepEqual(withGradeSuffix([{ id: "a", name: "Make Inferences", code: "G4.inf" }, { id: "b", name: "Make Inferences", code: "G5.inf" }, { id: "c", name: "Theme", code: "G5.theme" }]).map((x) => x.name), ["Make Inferences · G4", "Make Inferences · G5", "Theme"]);
    const backup = await rosterBackup(repo, admin, { kind: "CLASS", classId }) as { tables: Record<string, Record<string, unknown>[]> };
    assert.equal(backup.tables.AdaptiveDecisionLog, undefined, "the engine's decision trail is left out");
    assert.ok(backup.tables.QuestionAttempt.length > 0 && backup.tables.QuestionAttempt.every((r) => !("difficultyB" in r) && "isCorrect" in r && "response" in r));
    assert.match(readFileSync(join(ROOT, "src/lib/env.ts"), "utf8"), /LOGIN_RATE_LIMIT_PER_IP: z\.coerce\.number\(\)\.int\(\)\.min\(20\)\.max\(100_000\)\.default\(2000\)/);
    assert.match(readFileSync(join(ROOT, "src/server/auth/next.ts"), "utf8"), /rateLimitPerIp: env\.LOGIN_RATE_LIMIT_PER_IP/);
    const run = (daysAgo: number) => ({ completedAt: new Date(now.getTime() - daysAgo * DAY) });
    const falling = [0, 1, 2, 3, 4, 5, 6, 7, 8].map((w) => ({ at: new Date(now.getTime() - (8 - w) * 7 * DAY), level: 700 - w * 50 }));
    assert.equal(await readRiseProjection(repo, [run(20), run(10), run(1)], falling, String(admin.schoolId), now), null, "3 runs: no projection yet");
    assert.equal(await readRiseProjection(repo, [run(5), run(4), run(3), run(1)], falling, String(admin.schoolId), now), null, "4 runs in 4 days: no projection yet");
    const p = await readRiseProjection(repo, [run(20), run(15), run(10), run(1)], falling, String(admin.schoolId), now);
    assert.ok(p !== null && p >= RR_MIN, `on the ReadRise scale, never “about 200” (${p})`);
  });

  // ------------------------------------------------------------------ styles
  test("I-2: admin styles are ONE module that exports everything its importers use; no .ts/.tsx twins anywhere", () => {
    assert.equal(existsSync(join(ROOT, "src/components/admin/styles.ts")), false);
    const mod = readFileSync(join(ROOT, "src/components/admin/styles.tsx"), "utf8");
    const exported = new Set([...mod.matchAll(/export (?:const|function) (\w+)/g)].map((m) => m[1]));
    for (const k of ["field", "label", "card", "h2", "btnLink", "AdminCard", "AdminTitle"]) assert.ok(exported.has(k), k);
    const files: string[] = [];
    const walk = (d: string) => { for (const f of readdirSync(d)) { const p = join(d, f); if (statSync(p).isDirectory()) walk(p); else if (/\.(ts|tsx)$/.test(f)) files.push(p); } };
    walk(join(ROOT, "src"));
    const missing: string[] = [];
    for (const f of files) {
      for (const m of readFileSync(f, "utf8").matchAll(/import \{([^}]+)\} from "@\/components\/admin\/styles"/g)) for (const n of m[1].split(",").map((x) => x.trim()).filter(Boolean)) if (!exported.has(n)) missing.push(`${f}: ${n}`);
    }
    assert.deepEqual(missing, []);
    const base = new Set(files.filter((f) => f.endsWith(".ts")).map((f) => f.slice(0, -3)));
    assert.deepEqual(files.filter((f) => f.endsWith(".tsx") && base.has(f.slice(0, -4))), [], "webpack (.tsx first) and tsc (.ts first) would resolve differently");
  });

  // ------------------------------------------------------------------ test-school removal (last: deletes the Test School)
  test("I-6: removing the Test School leaves no row pointing at a deleted user, student, class or school; the other school is intact", async () => {
    const schoolId = String(admin.schoolId);
    // rows in tables WITHOUT a Prisma relation (the 45 tables that kept 27,445 rows)
    await scanDailyAlerts(repo, schoolId, new Date(now.getTime() + 10 * DAY));
    await computeTiers(repo, schoolId, now, { route: false });
    const sid = students[1];
    await repo.create("StudentWord", { studentId: sid, word: "brave", lastAt: now, createdAt: now } as never).catch(() => null);
    await repo.create("StudentProfile", { studentId: sid, schoolId, updatedAt: now } as never).catch(() => null);
    await repo.create("TeacherNote", { schoolId, studentId: sid, authorId: teacher.userId, body: "note", createdAt: now } as never).catch(() => null);
    const demo = (await repo.findMany("School", {})).find((s) => s.code !== TEST_SCHOOL_CODE)!;
    const demoCounts = async () => ({
      users: await repo.count("User", { schoolId: demo.id }), students: await repo.count("Student", { schoolId: demo.id }), classes: await repo.count("Class", { schoolId: demo.id }),
      attempts: (await repo.findMany("Student", { schoolId: demo.id }, { select: ["id"] })).length,
    });
    const before0 = await demoCounts();
    const school = await repo.findUnique("School", { code: TEST_SCHOOL_CODE });
    const gone = {
      School: [String(school!.id)],
      User: (await repo.findMany("User", { schoolId: school!.id }, { select: ["id"] })).map((u) => String(u.id)),
      Student: (await repo.findMany("Student", { schoolId: school!.id }, { select: ["id"] })).map((u) => String(u.id)),
      Class: (await repo.findMany("Class", { schoolId: school!.id }, { select: ["id"] })).map((u) => String(u.id)),
    };
    assert.ok((await repo.count("StudentAlert", { schoolId: school!.id })) > 0 && (await repo.count("StudentTier", { schoolId: school!.id })) > 0, "non-relation rows exist before");
    await resetTestEnvironment(repo);
    const schema = parseSchema(join(ROOT, "prisma/schema.prisma"));
    const problems: string[] = [];
    // every table, every column that names a user / student / class / school
    for (const m of schema.models.values()) {
      for (const f of m.fields) {
        const target = ({ userId: "User", studentId: "Student", classId: "Class", schoolId: "School", actorId: "User" } as Record<string, keyof typeof gone>)[f.name];
        if (!target || f.relation) continue;
        const ids = gone[target];
        for (let i = 0; i < ids.length; i += 400) {
          const part = ids.slice(i, i + 400);
          const n = (db.prepare(`SELECT COUNT(*) AS n FROM "${m.name}" WHERE "${f.name}" IN (${part.map(() => "?").join(",")})`).get(...part) as { n: number }).n;
          if (n) problems.push(`${m.name}.${f.name}: ${n}`);
        }
      }
    }
    assert.deepEqual(problems, [], "no row references a deleted user, student, class or school");
    // and nothing in any ownership chain is left without its parent
    const orphans: string[] = [];
    for (const [parent, list] of ownershipEdges(schema)) {
      const pid = schema.models.get(parent)!.id[0];
      for (const e of list) {
        if (e.optional) continue;
        const n = (db.prepare(`SELECT COUNT(*) AS n FROM "${e.child}" c WHERE c."${e.fk}" IS NOT NULL AND NOT EXISTS (SELECT 1 FROM "${parent}" p WHERE p."${pid}" = c."${e.fk}")`).get() as { n: number }).n;
        if (n) orphans.push(`${e.child}.${e.fk} → ${parent}: ${n}`);
      }
    }
    assert.deepEqual(orphans, [], "no orphan in any ownership chain");
    assert.deepEqual(await demoCounts(), before0, "the other school is intact");
  });
});
